/*
 * Test için sahte 'webos-service' modülü (gerçeği yalnızca LG TV'de vardır). test_webos_service.py kullanır.
 * Servis 'start' yöntemini kaydedince ona abone olur; gelen her yanıtı stdout'a JSON satırı olarak yazar.
 * stdin'den gelen satır bir yöntem adıdır ("newCode", "state", "cancel"), ardından isteğe bağlı JSON yükü
 * ("drawn {\"id\":7}"), ve o yöntem çağrılır.
 */
var readline = require('readline');

function Service(id) {
    this.id = id;
    this.methods = {};
    var self = this;
    this.activityManager = {
        create: function (name, cb) { setTimeout(function () { cb({ name: name }); }, 0); },
        complete: function (activity, cb) { if (cb) cb(); }
    };
    setTimeout(function () { self._subscribe(); }, 50);
    readline.createInterface({ input: process.stdin }).on('line', function (line) {
        var text = line.trim();
        var sp = text.indexOf(' ');
        var name = sp < 0 ? text : text.slice(0, sp);
        var payload = sp < 0 ? null : JSON.parse(text.slice(sp + 1));
        if (name === 'cancel') { self.methods.start.cancel({ uniqueToken: 'test' }); return; }
        if (self.methods[name]) self._call(name, false, payload);
    });
}

Service.prototype.register = function (name, cb, cancel) {
    this.methods[name] = { cb: cb, cancel: cancel };
};

Service.prototype._message = function (name, isSubscription, payload) {
    return {
        payload: payload || { name: 'Test LG TV', subscribe: isSubscription },
        isSubscription: isSubscription,
        uniqueToken: 'test',
        respond: function (p) { process.stdout.write(JSON.stringify({ method: name, response: p }) + '\n'); }
    };
};

Service.prototype._subscribe = function () {
    this.methods.start.cb(this._message('start', true));
};

Service.prototype._call = function (name, isSubscription, payload) {
    this.methods[name].cb(this._message(name, isSubscription, payload));
};

module.exports = Service;
